import 'package:drift/drift.dart';
import 'package:drift/native.dart';
import 'dart:io';

import 'package:path_provider/path_provider.dart';
import 'package:path/path.dart' as p;

import 'tables.dart';

part 'app_database.g.dart';

/// Main Drift database — all 12 local tables.
///
/// Code generated by `dart run build_runner build`.
@DriftDatabase(
  tables: [
    // Cache tables
    CachedTemplates,
    CachedGroups,
    CachedCriteria,
    CachedStores,
    CachedSubmissions,
    CachedActionPlans,
    CachedNotifications,
    // Outbox tables
    PendingSubmissions,
    PendingAnswers,
    PendingPhotos,
    // Metadata
    SyncMeta,
    // Drafts
    DraftAnswers,
  ],
)
class AppDatabase extends _$AppDatabase {
  AppDatabase() : super(_openConnection());

  /// For testing — accepts a custom executor.
  AppDatabase.forTesting(super.e);

  @override
  int get schemaVersion => 6;

  @override
  MigrationStrategy get migration => MigrationStrategy(
    onCreate: (Migrator m) async {
      await m.createAll();
    },
    onUpgrade: (Migrator m, int from, int to) async {
      if (from < 2) {
        await m.addColumn(cachedStores, cachedStores.areaId);
        await m.addColumn(cachedStores, cachedStores.areaName);
      }
      if (from < 3) {
        await m.addColumn(cachedGroups, cachedGroups.minusPerFault);
      }
      if (from < 4) {
        await m.createTable(draftAnswers);
      }
      if (from < 5) {
        await m.addColumn(
          cachedSubmissions,
          cachedSubmissions.templateSnapshot,
        );
        await m.addColumn(cachedSubmissions, cachedSubmissions.templateVersion);
      }
      if (from < 6) {
        await m.addColumn(cachedActionPlans, cachedActionPlans.storeId);
      }
    },
  );
}

LazyDatabase _openConnection() {
  return LazyDatabase(() async {
    final dir = await getApplicationDocumentsDirectory();
    final file = File(p.join(dir.path, 'checkly_local.db'));
    return NativeDatabase.createInBackground(file, setup: (db) {
      // Diagnostic check for JSON1 extension (required for JSONB columns)
      try {
        db.execute("SELECT json_valid('{}')");
      } catch (e) {
        throw Exception('FATAL: Compiled sqlite3 binary is missing JSON1 extension support. $e');
      }
    });
  });
}
